<script setup lang="ts">
import { computed } from 'vue';
const props = withDefaults(defineProps<{status:string;label?:string;domain?:'task'|'run'|'delivery'|'connection'|'configuration'}>(),{domain:'task'});
const labels:Record<string,string>={succeeded:'已完成',failed:'失败',sent:'已送达',enabled:'已启用',disabled:'已停用',unknown:'结果待核对',planned:'待办',queued:'排队中',running:'执行中',canceled:'已取消',cancel_requested:'申请取消',waiting_input:'等待输入',waiting_approval:'等待确认',waiting_human:'等待人工',needs_human:'人工等待段已结束',available:'可用',unavailable:'不可用',verified:'身份已验证',pending_verification:'待验证',pending:'待投递',sending:'投递中',completed:'已结束',starting:'启动中',interrupted:'已中断',timed_out:'已超时',partial:'部分送达',error:'连接异常',not_configured:'未接入',confirmed:'已确认',blocked:'受阻'};
const text=computed(()=>props.label??(props.domain==='delivery'?({failed:'投递失败',unknown:'送达未知',succeeded:'已送达'} as Record<string,string>)[props.status]:props.domain==='run'?({running:'运行中',succeeded:'已结束',failed:'执行失败'} as Record<string,string>)[props.status]:undefined)??labels[props.status]??props.status);
const tone=computed(()=>props.status==='unknown'?'unknown':['failed','invalid','error','interrupted','blocked'].includes(props.status)?'danger':['pending_verification','waiting_input','waiting_approval','waiting_human','timed_out','partial'].includes(props.status)?'warning':['running','starting','sending'].includes(props.status)?'info':['succeeded','sent','available','verified','completed','confirmed'].includes(props.status)?'success':'neutral');
const paths:Record<string,string>={success:'M5 12l4 4L19 6',danger:'M8 8l8 8M16 8l-8 8',warning:'M12 7v6M12 17h.01',info:'M12 5v7l4 2',neutral:'M12 6v6l-3 3',unknown:'M9 9a3 3 0 1 1 5 2c-2 1-2 2-2 3M12 17h.01'};
</script>
<template><span class="status-badge" :class="`status-badge--${tone}`" :data-status="status" :data-domain="domain"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path :d="status==='enabled'?paths.success:paths[tone]"/></svg>{{text}}</span></template>
