.status-badge{--badge-fg:var(--id-status-neutral-fg);--badge-bg:var(--id-status-neutral-bg);display:inline-flex;align-items:center;gap:4px;max-width:100%;padding:1px 7px;border:1px solid color-mix(in srgb,var(--badge-fg) 25%,transparent);border-radius:999px;background:var(--badge-bg);color:var(--badge-fg);font-size:12px;line-height:18px;white-space:nowrap;font-weight:400}.status-badge svg{width:13px;height:13px;flex:none}.status-badge--success{--badge-fg:var(--id-status-success-fg);--badge-bg:var(--id-status-success-bg)}.status-badge--danger{--badge-fg:var(--id-status-danger-fg);--badge-bg:var(--id-status-danger-bg)}.status-badge--warning{--badge-fg:var(--id-status-warning-fg);--badge-bg:var(--id-status-warning-bg)}.status-badge--info{--badge-fg:var(--id-status-info-fg);--badge-bg:var(--id-status-info-bg)}.status-badge--unknown{--badge-fg:var(--id-status-unknown-fg);--badge-bg:var(--id-status-unknown-bg);border-style:dashed}
</style>
